-- Phase 7: HRMS employee records, shifts, attendance, leave, payroll, performance and documents.
create sequence public.employee_number_seq;
create table public.hr_employees(id uuid primary key default gen_random_uuid(),staff_profile_id uuid unique references public.staff_profiles(id),employee_code text not null unique default('AECS-EMP-'||lpad(nextval('employee_number_seq')::text,4,'0')),full_name text not null,email citext not null unique,phone text,job_title text not null,department text not null,branch text not null,join_date date not null default current_date,employment_status text not null default'ACTIVE'check(employment_status in('ACTIVE','ON_LEAVE','PROBATION','SUSPENDED','EXITED')),base_salary numeric(14,2)not null default 0 check(base_salary>=0),bank_account text,pan_number text,created_by uuid not null references public.staff_profiles(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.hr_shifts(id uuid primary key default gen_random_uuid(),name text not null unique,start_time time not null,end_time time not null,grace_minutes integer not null default 15 check(grace_minutes between 0 and 180),weekly_days smallint[]not null default'{1,2,3,4,5,6}',is_active boolean not null default true,created_at timestamptz not null default now());
create table public.hr_shift_assignments(id uuid primary key default gen_random_uuid(),employee_id uuid not null references public.hr_employees(id)on delete cascade,shift_id uuid not null references public.hr_shifts(id),effective_from date not null,effective_to date,unique(employee_id,effective_from));
create table public.hr_attendance(id uuid primary key default gen_random_uuid(),employee_id uuid not null references public.hr_employees(id)on delete cascade,attendance_date date not null default current_date,clock_in timestamptz,clock_out timestamptz,status text not null default'PRESENT'check(status in('PRESENT','LATE','HALF_DAY','ON_LEAVE','ABSENT')),late_minutes integer not null default 0 check(late_minutes>=0),source text not null default'WEB'check(source in('WEB','BIOMETRIC','MANUAL')),approved_by uuid references public.staff_profiles(id),unique(employee_id,attendance_date));
create table public.hr_leave_requests(id uuid primary key default gen_random_uuid(),employee_id uuid not null references public.hr_employees(id)on delete cascade,leave_type text not null,from_date date not null,to_date date not null check(to_date>=from_date),days numeric(5,1)not null check(days>0),reason text not null,status text not null default'PENDING'check(status in('PENDING','APPROVED','REJECTED','CANCELLED')),approved_by uuid references public.staff_profiles(id),decision_note text,created_at timestamptz not null default now());
create table public.hr_payroll_runs(id uuid primary key default gen_random_uuid(),period_start date not null,period_end date not null check(period_end>=period_start),status text not null default'DRAFT'check(status in('DRAFT','PENDING_APPROVAL','APPROVED','PAID','CANCELLED')),prepared_by uuid not null references public.staff_profiles(id),approved_by uuid references public.staff_profiles(id),paid_at timestamptz,unique(period_start,period_end));
create table public.hr_payroll_items(id uuid primary key default gen_random_uuid(),payroll_run_id uuid not null references public.hr_payroll_runs(id)on delete cascade,employee_id uuid not null references public.hr_employees(id),basic_salary numeric(14,2)not null,allowance numeric(14,2)not null default 0,commission numeric(14,2)not null default 0,ssf_deduction numeric(14,2)not null default 0,cit_deduction numeric(14,2)not null default 0,tds_tax numeric(14,2)not null default 0,gross_salary numeric(14,2)generated always as(basic_salary+allowance+commission)stored,net_salary numeric(14,2)generated always as(basic_salary+allowance+commission-ssf_deduction-cit_deduction-tds_tax)stored,unique(payroll_run_id,employee_id));
create table public.hr_performance_reviews(id uuid primary key default gen_random_uuid(),employee_id uuid not null references public.hr_employees(id)on delete cascade,review_period text not null,rating numeric(3,2)not null check(rating between 1 and 5),goals text,manager_feedback text,reviewed_by uuid not null references public.staff_profiles(id),reviewed_at timestamptz not null default now());
create table public.hr_staff_documents(id uuid primary key default gen_random_uuid(),employee_id uuid not null references public.hr_employees(id)on delete cascade,document_type text not null,file_name text not null,storage_path text not null unique,expires_on date,uploaded_by uuid not null references public.staff_profiles(id),created_at timestamptz not null default now());
insert into public.hr_shifts(name,start_time,end_time,grace_minutes)values('Standard Office','09:30','17:30',15),('Morning Classes','06:30','14:30',10)on conflict(name)do nothing;
insert into public.permissions(role,permission_name,enabled)select role,permission_name,true from(values('ADMIN'::public.staff_role),('DIRECTOR'))r(role)cross join(values('hr.view'),('hr.manage'),('hr.approve'),('payroll.view'),('payroll.manage'))p(permission_name)on conflict(role,permission_name)do update set enabled=true;
insert into public.permissions(role,permission_name,enabled)select role,'hr.self_service',true from unnest(enum_range(null::public.staff_role))role on conflict(role,permission_name)do update set enabled=true;
do $$declare t text;begin foreach t in array array['hr_employees','hr_shifts','hr_shift_assignments','hr_attendance','hr_leave_requests','hr_payroll_runs','hr_payroll_items','hr_performance_reviews','hr_staff_documents']loop execute format('alter table public.%I enable row level security',t);execute format('create policy %I_admin_read on public.%I for select to authenticated using(public.has_permission(''hr.view''))',t,t);end loop;end$$;
create policy hr_employee_self_read on public.hr_employees for select to authenticated using(staff_profile_id=auth.uid());
create policy hr_attendance_self_read on public.hr_attendance for select to authenticated using(employee_id in(select id from public.hr_employees where staff_profile_id=auth.uid()));
create policy hr_leave_self_read on public.hr_leave_requests for select to authenticated using(employee_id in(select id from public.hr_employees where staff_profile_id=auth.uid()));
create or replace function public.hr_create_employee(payload jsonb)returns uuid language plpgsql security definer set search_path=public as $$declare eid uuid;begin if not public.has_permission('hr.manage')then raise exception'Insufficient permission';end if;insert into hr_employees(full_name,email,phone,job_title,department,branch,join_date,base_salary,bank_account,pan_number,created_by)values(payload->>'full_name',(payload->>'email')::citext,payload->>'phone',payload->>'job_title',payload->>'department',payload->>'branch',coalesce((payload->>'join_date')::date,current_date),(payload->>'base_salary')::numeric,payload->>'bank_account',payload->>'pan_number',auth.uid())returning id into eid;return eid;end$$;
create or replace function public.hr_clock_in()returns uuid language plpgsql security definer set search_path=public as $$declare eid uuid;aid uuid;shift record;late integer:=0;begin select id into eid from hr_employees where staff_profile_id=auth.uid()and employment_status in('ACTIVE','PROBATION');if eid is null then raise exception'Active employee record not found';end if;select s.* into shift from hr_shifts s join hr_shift_assignments a on a.shift_id=s.id where a.employee_id=eid and a.effective_from<=current_date and(a.effective_to is null or a.effective_to>=current_date)order by a.effective_from desc limit 1;if shift.id is not null then late:=greatest(0,extract(epoch from(localtime-(shift.start_time+make_interval(mins=>shift.grace_minutes))))::integer/60);end if;insert into hr_attendance(employee_id,clock_in,status,late_minutes)values(eid,now(),case when late>0 then'LATE'else'PRESENT'end,late)on conflict(employee_id,attendance_date)do update set clock_in=coalesce(hr_attendance.clock_in,excluded.clock_in)returning id into aid;return aid;end$$;
create or replace function public.hr_request_leave(payload jsonb)returns uuid language plpgsql security definer set search_path=public as $$declare eid uuid;lid uuid;begin select id into eid from hr_employees where staff_profile_id=auth.uid();if eid is null and public.has_permission('hr.manage')then select id into eid from hr_employees where employee_code=payload->>'employee_code';end if;if eid is null then raise exception'Employee record not found';end if;insert into hr_leave_requests(employee_id,leave_type,from_date,to_date,days,reason)values(eid,payload->>'leave_type',(payload->>'from_date')::date,(payload->>'to_date')::date,(payload->>'days')::numeric,payload->>'reason')returning id into lid;return lid;end$$;
create or replace function public.hr_decide_leave(leave_uuid uuid,decision text,decision_note text default null)returns void language plpgsql security definer set search_path=public as $$begin if not public.has_permission('hr.approve')then raise exception'Insufficient permission';end if;if decision not in('APPROVED','REJECTED')then raise exception'Invalid decision';end if;update hr_leave_requests set status=decision,approved_by=auth.uid(),decision_note=hr_decide_leave.decision_note where id=leave_uuid and status='PENDING';if not found then raise exception'Pending leave request not found';end if;end$$;
revoke all on function public.hr_create_employee(jsonb),public.hr_clock_in(),public.hr_request_leave(jsonb),public.hr_decide_leave(uuid,text,text)from public;grant execute on function public.hr_create_employee(jsonb),public.hr_clock_in(),public.hr_request_leave(jsonb),public.hr_decide_leave(uuid,text,text)to authenticated;
